CREATE SCHEMA IF NOT EXISTS modoo;
REVOKE ALL ON SCHEMA modoo FROM PUBLIC,anon,authenticated;
CREATE TABLE modoo.config(key text PRIMARY KEY,value text NOT NULL);
CREATE TABLE modoo.teams(id text PRIMARY KEY,name text UNIQUE NOT NULL,salt text NOT NULL,hash text NOT NULL,created double precision NOT NULL,mentor integer NOT NULL DEFAULT 0,mentee integer NOT NULL DEFAULT 0,mentor_played integer NOT NULL DEFAULT 0,mentee_played integer NOT NULL DEFAULT 0);
CREATE TABLE modoo.participants(id text PRIMARY KEY,team text NOT NULL REFERENCES modoo.teams(id) ON DELETE CASCADE,name text NOT NULL,role text NOT NULL CHECK(role IN ('mentor','mentee')),salt text NOT NULL,hash text NOT NULL,UNIQUE(team,role),UNIQUE(team,name));
CREATE TABLE modoo.invitations(team text PRIMARY KEY REFERENCES modoo.teams(id) ON DELETE CASCADE,salt text NOT NULL,hash text NOT NULL);
CREATE TABLE modoo.sessions(token text PRIMARY KEY,team text NOT NULL REFERENCES modoo.teams(id) ON DELETE CASCADE,expires double precision NOT NULL,role text,participant text REFERENCES modoo.participants(id) ON DELETE CASCADE);
CREATE TABLE modoo.rounds(id text PRIMARY KEY,token text NOT NULL,team text NOT NULL REFERENCES modoo.teams(id) ON DELETE CASCADE,role text NOT NULL,started double precision NOT NULL,score integer);
CREATE TABLE modoo.monthly_scores(team text NOT NULL REFERENCES modoo.teams(id) ON DELETE CASCADE,month text NOT NULL,mentor integer NOT NULL DEFAULT 0,mentee integer NOT NULL DEFAULT 0,mentor_played integer NOT NULL DEFAULT 0,mentee_played integer NOT NULL DEFAULT 0,PRIMARY KEY(team,month));
CREATE TABLE modoo.limits(key text PRIMARY KEY,count integer NOT NULL,reset double precision NOT NULL);
CREATE INDEX rounds_token_started ON modoo.rounds(token,started);
CREATE INDEX sessions_expires ON modoo.sessions(expires);
CREATE INDEX limits_reset ON modoo.limits(reset);
ALTER TABLE modoo.config ENABLE ROW LEVEL SECURITY;
ALTER TABLE modoo.teams ENABLE ROW LEVEL SECURITY;
ALTER TABLE modoo.participants ENABLE ROW LEVEL SECURITY;
ALTER TABLE modoo.invitations ENABLE ROW LEVEL SECURITY;
ALTER TABLE modoo.sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE modoo.rounds ENABLE ROW LEVEL SECURITY;
ALTER TABLE modoo.monthly_scores ENABLE ROW LEVEL SECURITY;
ALTER TABLE modoo.limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA modoo FROM PUBLIC,anon,authenticated;
